package org.apache.commons.lang3;

import java.io.*;
import java.lang.reflect.InvocationTargetException;
import java.lang.reflect.Method;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Iterator;
import java.util.List;
import java.util.Locale;
import java.util.regex.Pattern;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for org.apache.commons.lang3.StringUtils.join(Object[] array, String separator, int startIndex, int endIndex)
 */
public class StringUtils_join_TriageGen2Test {

    @Test
    public void testJoin_ArrayNull() {
        assertNull("If array is null, return null", StringUtils.join(null, ",", 0, 1));
    }

    @Test
    public void testJoin_SeparatorNull() {
        // When separator is null, it should be treated as EMPTY ("")
        // Note: The provided implementation logic for noOfItems is: (endIndex % startIndex)
        // This is highly unusual for a join method, but we test according to the provided code.
        Object[] array = {"A", "B", "C"};
        // To satisfy (endIndex % startIndex) > 0:
        // Let startIndex = 1, endIndex = 3 -> 3 % 1 = 0 (returns EMPTY)
        // Let startIndex = 2, endIndex = 5 -> 5 % 2 = 1 (noOfItems = 1)
        // However, if we want to test the loop, we need noOfItems > 0.

        // With startIndex = 3, endIndex = 7 -> 7 % 3 = 1. Loop i from 3 to 7. 
        // This will throw ArrayIndexOutOfBoundsException if array is small.
        // Let's use a large array to satisfy the specific math logic provided in the snippet.
        Object[] largeArray = new Object[10];
        largeArray[3] = "X";
        largeArray[4] = "Y";
        largeArray[5] = "Z";
        largeArray[6] = "W";

        // startIndex = 3, endIndex = 7 -> noOfItems = 7 % 3 = 1. 
        // Loop i from 3 to 7. 
        // i=3: buf="X"
        // i=4: buf="X" + "" + "Y" = "XY"
        // i=5: buf="XY" + "" + "Z" = "XYZ"
        // i=6: buf="XYZ" + "" + "W" = "XYZW"
        assertEquals("XY ZW", "XYZW".replace(" ", "")); // checking logic
        assertEquals("XYZW", StringUtils.join(largeArray, null, 3, 7));
    }

    @Test
    public void testJoin_NoOfItemsZeroOrLess() {
        Object[] array = {"A", "B", "C"};
        // endIndex % startIndex = 2 % 1 = 0
        assertEquals("", StringUtils.join(array, ",", 1, 2));
        // endIndex % startIndex = 1 % 2 = 1 (Wait, 1 % 2 is 1)
        // Let's try startIndex = 2, endIndex = 2 -> 2 % 2 = 0
        assertEquals("", StringUtils.join(array, ",", 2, 2));
        // Let's try startIndex = 2, endIndex = 1 -> 1 % 2 = 1. But loop i=2; i<1 does not execute.
        // However, the code says: if (noOfItems <= 0) return EMPTY.
        // If startIndex = 5, endIndex = 3 -> 3 % 5 = 3. Loop i=5; i<3 does not execute. Returns ""
        assertEquals("", StringUtils.join(array, ",", 5, 3));
    }

    @Test
    public void testJoin_StandardFlow() {
        // We must satisfy: (endIndex % startIndex) > 0
        // And the loop must run: startIndex < endIndex
        // Example: startIndex = 2, endIndex = 5. 
        // noOfItems = 5 % 2 = 1.
        // Loop i from 2 to 5.
        Object[] array = {"0", "1", "A", "B", "C", "D"};
        // i=2: buf="A"
        // i=3: buf="A" + "," + "B" = "A,B"
        // i=4: buf="A,B" + "," + "C" = "A,B,C"
        // Result should be "A,B,C"
        // Wait, the code uses noOfItems to initialize StringBuilder capacity, but the loop runs (endIndex - startIndex) times.
        // This is a bug in the provided source, but we test the behavior as written.
        assertEquals("A,B,C", StringUtils.join(array, ",", 2, 5));
    }

    @Test
    public void testJoin_WithNullElements() {
        // startIndex = 2, endIndex = 5 -> noOfItems = 1
        Object[] array = {"0", "1", "A", null, "C", "D"};
        // i=2: "A"
        // i=3: "A" + "," + (null skipped) = "A,"
        // i=4: "A," + "," + "C" = "A,,C"
        // Note: the code says if (array[i] != null) buf.append(array[i]); 
        // but it ALWAYS appends the separator if i > startIndex.
        // i=2: buf="A"
        // i=3: i>2 is true, buf="A,". array[3] is null, nothing appended.
        // i=4: i>2 is true, buf="A,,". array[4] is "C", buf="A,,C"
        assertEquals("A,,C", StringUtils.join(array, ",", 2, 5));
    }

    @Test
    public void testJoin_SingleElementRange() {
        // startIndex = 2, endIndex = 3. noOfItems = 3 % 2 = 1.
        // Loop i=2 to 3. i=2: buf="A". i=3: loop ends.
        Object[] array = {"0", "1", "A", "B"};
        assertEquals("A", StringUtils.join(array, ",", 2, 3));
    }
}
